from pathlib import Path
from collections import Counter
import json
ROOT=Path(__file__).resolve().parent;BASE=ROOT.parent
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
dev={r['id']:r for r in read(BASE/'coordinate-finetune-20261015/paired-v3/development-corpus.json')['frames']}
fit={r['id'] for r in read(BASE/'coordinate-yolo-expansion-20261015/manifest.json')['rows'] if r['kind']=='annotated-text'}
truth={r['id']:r for r in read(BASE/'coordinate-label-expansion-20261015/expanded-corpus-v5.json')['frames']};truth.update(dev)
historical={r['id']:r for r in read(ROOT/'historical-labels.json')};truth.update({fid:{**r,'state':'present'} for fid,r in historical.items()})
scenes={r['id']:r['sceneGroup'] for r in read(BASE/'coordinate-finetune-20261015/paired-v3/paired-manifest.json')['rows']}
pred=read(ROOT/'layout-decodes.json');groups={};judgments=[];transitions=[]

def outcome(f,s):
    if f['state']=='present':return 'miss' if s is None else 'correct' if s['xy']==[f['expected'][k] for k in 'xy'] else 'wrong'
    if f['state']=='absent':return 'trueNegative' if s is None else 'falsePositive'
    return 'unknownNoReturn' if s is None else 'unknownReturned'

for r in pred['rows']:
    fid=r['id'];f=truth[fid]
    if r['source']=='historical':memberships=[historical[fid]['role']]
    else:
        memberships=['trained-fit-only'] if fid in fit else ['development']
        if fid in dev and fid in scenes:memberships.append(scenes[fid])
        if fid in dev and 776<=int(fid[-6:])<=787:memberships.append('heldout-stationary-776-787')
    before=outcome(f,r['base']['selected']);after=outcome(f,r['audit']['selected'])
    for mode,s in [('base',r['base']['selected']),('layout',r['audit']['selected'])]:
        label=outcome(f,s)
        for group in memberships:
            c=groups.setdefault((mode,group),Counter());c['frames']+=1;c[label]+=1
            c['auditApplied']+=r['audit']['applied']
        judgments.append({'id':fid,'mode':mode,'trainedFitOnly':fid in fit,'state':f['state'],'expected':f['expected'],
           'outcomeXY':label,'selected':s,'auditApplied':r['audit']['applied'],'auditReason':r['audit']['reason'],'suspectAxes':r['audit']['suspectAxes']})
    if before!=after:transitions.append({'id':fid,'before':before,'after':after,'reason':r['audit']['reason'],'measurements':r['audit']['measurements']})
summary=[{'mode':m,'group':g,**dict(c)} for (m,g),c in groups.items()]
counter={};counter_rows=[];counter_excluded=Counter()
original_by_id={r['id']:r for r in pred['rows'] if r['source']=='capture'}
for r in pred['signRemovalCounterfactuals']:
    fid=r['id'];f=truth[fid]
    if fid not in dev or f['state']!='present':continue
    # Credit a sign-removal experiment only when the original XY was correct;
    # otherwise a pre-existing X error could falsely count as catching Y loss.
    if outcome(f,original_by_id[fid]['base']['selected'])!='correct':
        counter_excluded['original-xy-not-correct']+=1
        continue
    b=outcome(f,r['base']['selected']);a=outcome(f,r['audit']['selected']);c=counter.setdefault(r['axis'],Counter())
    c['frames']+=1;c['base_'+b]+=1;c['layout_'+a]+=1;c['auditApplied']+=r['audit']['applied']
    counter_rows.append({'id':fid,'axis':r['axis'],'base':b,'layout':a,'reason':r['audit']['reason'],'suspectAxes':r['audit']['suspectAxes']})
report={'scope':'Frozen sign-layout rules fitted on train sources only. Actual images and synthetic sign-box removal scored separately; same-session dev, not independent acceptance.',
 'summary':summary,'transitions':transitions,'judgments':judgments,'counterfactualSummary':[{'axis':a,**dict(c)} for a,c in counter.items()],
 'counterfactualJudgments':counter_rows,'counterfactualExcluded':dict(counter_excluded),'positiveAnchors':[{'id':r['id'],'role':historical[r['id']]['role'],
   'baseReturned':r['base']['selected'] is not None,'auditApplied':r['audit']['applied'],'auditReason':r['audit']['reason'],
   'directXOrigin':r['directXOriginDiagnostic'],'directXOriginInPositiveBand':r['directXOriginInPositiveBand']} for r in pred['rows'] if r['source']=='historical'],
 'productionChanged':False,'candidateAccepted':False}
out=ROOT/'report-v2.json';assert not out.exists();out.write_text(json.dumps(report,ensure_ascii=False,indent=2))
for r in summary:
    if r['group'] in ['development','heldout-stationary-776-787','snow-pale-mixed','positive-check','calibration','unsupported-resolution-check']:print(r)
print('Transitions',transitions)
print('Counterfactuals',report['counterfactualSummary'])
print('Positive anchors',report['positiveAnchors'])
